mapper.select:
SELECT a.id, a.issue_id, a.user_id, a.action, a.field_name, , a.created_at, u.display_name AS user_name, u.avatar_url AS user_avatar, i.issue_key, i.title AS issue_title FROM issue_activity a LEFT JOIN sys_user u ON u.id = a.user_id LEFT JOIN issue i ON i.id = a.issue_id WHERE a.issue_id IN
#{id}
AND NOT (a.old_value IS NOT NULL AND a.new_value IS NOT NULL AND a.old_value = a.new_value) ORDER BY a.created_at DESC LIMIT #{limit}

SELECT a.id, a.issue_id, a.user_id, a.action, a.field_name, , a.created_at, u.display_name AS user_name, u.avatar_url AS user_avatar, i.issue_key, i.title AS issue_title FROM issue_activity a INNER JOIN issue i ON i.id = a.issue_id AND i.deleted_at IS NULL LEFT JOIN sys_user u ON u.id = a.user_id WHERE i.project_id IN
#{pid}
AND NOT (a.old_value IS NOT NULL AND a.new_value IS NOT NULL AND a.old_value = a.new_value) ORDER BY a.created_at DESC LIMIT #{limit}

SELECT a.id, a.issue_id, a.user_id, a.action, a.field_name, , a.created_at, u.display_name AS user_name, u.avatar_url AS user_avatar, i.issue_key, i.title AS issue_title FROM issue_activity a INNER JOIN issue i ON i.id = a.issue_id AND i.deleted_at IS NULL LEFT JOIN sys_user u ON u.id = a.user_id WHERE 1=1 AND NOT (a.old_value IS NOT NULL AND a.new_value IS NOT NULL AND a.old_value = a.new_value)
AND i.project_id IN
#{pid}
AND a.action IN
#{act}
AND a.user_id IN
#{uid}
ORDER BY a.created_at DESC LIMIT #{limit}

SELECT id FROM issue
WHERE project_id = #{projectId}
  AND deleted_at IS NOT NULL
  AND deleted_at < #{cutoff}

SELECT cfv.issue_id AS id, CAST(cfv.value AS numeric) AS estimated_hours FROM custom_field_value cfv WHERE cfv.custom_field_id = #{fieldId} AND cfv.issue_id IN
#{id}
AND cfv.value IS NOT NULL AND cfv.value ~ '^-?[0-9]+(\.[0-9]+)?$'

SELECT i.id, i.project_id, p.key AS project_key, i.issue_key, i.title, i.issue_type, i.status_id, i.priority, i.assignee_id, i.sprint_id, i.due_date, i.estimated_hours, i.child_count, i.child_closed_count, i.created_at, i.resolved_at, i.parent_id, pi.issue_key AS parent_issue_key, pi.title AS parent_title, COALESCE(s.display_name, s.name) AS status_name, s.color AS status_color, u.display_name AS assignee_name, u.avatar_url AS assignee_avatar_url, sp.name AS sprint_name FROM issue i LEFT JOIN project p ON p.id = i.project_id LEFT JOIN issue_status s ON s.id = i.status_id LEFT JOIN sys_user u ON u.id = i.assignee_id LEFT JOIN sprint sp ON sp.id = i.sprint_id LEFT JOIN issue pi ON pi.id = i.parent_id AND pi.deleted_at IS NULL
LEFT JOIN issue_manual_order mo ON mo.issue_id = i.id AND mo.context_type = #{manualOrderContextType} AND mo.context_id = #{manualOrderContextId} AND mo.user_id IS NULL
WHERE i.project_id = #{projectId} AND i.deleted_at IS NULL
AND i.status_id IN
#{sid}
AND i.priority IN
#{p}
AND i.sprint_id = #{sprintId}
AND i.assignee_id = #{assigneeId}
AND (i.title ILIKE CONCAT('%', #{keyword}, '%') OR i.issue_key ILIKE CONCAT('%', #{keyword}, '%'))
AND ( s.is_closed = false OR i.resolved_at IS NULL OR i.resolved_at >= #{excludeDoneBefore} )
AND i.assignee_id IN
CAST(#{v} AS BIGINT)
AND i.priority IN
#{v}
AND i.issue_type IN
#{v}
AND i.sprint_id IN
CAST(#{v} AS BIGINT)
ORDER BY COALESCE(mo.position, 2147483647) ASC, i.created_at DESC
ORDER BY i.created_at DESC
LIMIT #{limit}

SELECT i.id, i.project_id, p.key AS project_key, i.issue_key, i.title, i.issue_type, i.status_id, i.priority, i.assignee_id, i.sprint_id, i.due_date, i.estimated_hours, i.child_count, i.child_closed_count, i.created_at, i.resolved_at, i.parent_id, pi.issue_key AS parent_issue_key, pi.title AS parent_title, COALESCE(s.display_name, s.name) AS status_name, s.color AS status_color, u.display_name AS assignee_name, u.avatar_url AS assignee_avatar_url, sp.name AS sprint_name FROM issue i LEFT JOIN project p ON p.id = i.project_id LEFT JOIN issue_status s ON s.id = i.status_id LEFT JOIN sys_user u ON u.id = i.assignee_id LEFT JOIN sprint sp ON sp.id = i.sprint_id LEFT JOIN issue pi ON pi.id = i.parent_id AND pi.deleted_at IS NULL WHERE i.project_id IN
#{pid}
AND i.deleted_at IS NULL
AND i.status_id IN
#{sid}
AND i.priority IN
#{pr}
AND i.sprint_id = #{sprintId}
AND i.assignee_id = #{assigneeId}
AND (i.title ILIKE CONCAT('%', #{keyword}, '%') OR i.issue_key ILIKE CONCAT('%', #{keyword}, '%'))
AND ( s.is_closed = false OR i.resolved_at IS NULL OR i.resolved_at >= #{excludeDoneBefore} )
AND i.assignee_id IN
CAST(#{v} AS BIGINT)
AND i.priority IN
#{v}
AND i.issue_type IN
#{v}
AND i.sprint_id IN
CAST(#{v} AS BIGINT)
ORDER BY i.created_at DESC LIMIT #{limit}

SELECT status_id, COUNT(*) AS cnt
FROM issue
WHERE deleted_at IS NULL
  AND status_id IN

        #{statusId}


    AND project_id = #{projectId}


    AND issue_type = #{issueType}

GROUP BY status_id
